import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';const before=JSON.parse(await readFile('.local/sequence-navigation/project-before.json','utf8'));const data=JSON.parse(await readFile(before.path,'utf8'));const hash=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');if(hash(data.scenes)!==before.scenesHash||hash(data.transcriptionJobs)!==before.transcriptHash)throw Error('Saved scenes or transcript changed');const t=performance.now();const r=await fetch('http://localhost:3211/',{signal:AbortSignal.timeout(3000)});await r.body.cancel();console.log({projectContentPreserved:true,scenes:data.scenes.length,status:r.status,healthMs:performance.now()-t});await writeFile('.local/sequence-navigation/preservation.json',JSON.stringify({projectContentPreserved:true,scenes:data.scenes.length,status:r.status}));
